// Given a string , WAM to return all its subsequences in an arraylist
// A String is a subsequence of a given String that is generated by
// deleting some character of a given string without hanging its order

// Input: abc
// output : a ,b , ab,bc,ac ,abc


import java.util.ArrayList;

public class Main {

     static ArrayList<String> getSubsequences(String str) {
        ArrayList<String> subsequences = new ArrayList<>();
        subsequences.add(""); // Start with an empty subsequence

        // Iterate over each character of the string
        for (char ch : str.toCharArray()) {
            int currentSize = subsequences.size();

            // Add the current character to all existing subsequences
            for (int i = 0; i < currentSize; i++) {
                subsequences.add(subsequences.get(i) + ch);
            }
        }

        subsequences.remove(""); // Remove the empty subsequence if needed
        return subsequences;
    }

    static ArrayList<String> getSSQ(String s){
         ArrayList<String> ans = new ArrayList<>();

         // base case
         if(s.length() == 0){
             ans.add("");
             return ans;
         }

        char curr = s.charAt(0); // a
        ArrayList<String> smallAns = getSSQ(s.substring(1)); // bc

        //smallAns = ["bc","b","c",""]
        // ans = ["bc","b","c","","abc","ab","ac","a"]

         for(String ss : smallAns){
             ans.add(ss);
             ans.add(curr + ss);
         }
         return ans;
    }

    public static void main(String[] args) {
        String input = "abc";
//        ArrayList<String> result = getSubsequences(input);
//        System.out.println(result);
        ArrayList<String> ans = getSSQ("abc");
        for(String ss : ans){
            System.out.print(ss + " ");
        }
    }
}